/**
 * Extract Manifest URL for Workflow 3 - Normalize webhook data structure
 * Handles both webhook body structure (first pass) and direct fields
 * FIX: Check top-level first (Wait node), then body (webhook), process ALL items
 * Handle null values properly - construct from orderId if manifestUrl is null
 * UPDATED: Uses 2B manifest (not 2A) and includes needed info for Workflow 3
 */
const inputs = $input.all();

return inputs.map(item => {
  const input = item.json;

  // Priority: Check top-level first (Wait node resume), then body (webhook first pass)
  // Wait node data has manifestUrl at top level, webhook has it in body
  // Handle null/empty string explicitly
  let manifestUrl = (input.manifestUrl && input.manifestUrl !== null && input.manifestUrl !== '') ? input.manifestUrl : null;
  if (!manifestUrl) {
    manifestUrl = (input.originalManifestUrl && input.originalManifestUrl !== null && input.originalManifestUrl !== '') ? input.originalManifestUrl : null;
  }

  let orderId = (input.orderId && input.orderId !== null && input.orderId !== '') ? input.orderId : null;
  if (!orderId) {
    orderId = (input.amazonOrderId && input.amazonOrderId !== null && input.amazonOrderId !== '') ? input.amazonOrderId : null;
  }

  // Fallback: Extract orderId from manifestKey if available (S3 node might have stripped orderId)
  if ((!orderId || orderId === null || orderId === '') && input.manifestKey) {
    const manifestKeyStr = String(input.manifestKey).trim();
    if (manifestKeyStr && manifestKeyStr !== 'null' && manifestKeyStr !== 'undefined') {
      // Try multiple patterns: /orders/{orderId}/ or orders/{orderId}/
      const patterns = [
        /[\/]orders[\/]([^\/]+)[\/]/,  // Matches /orders/TEST-ORDER-006/
        /orders[\/]([^\/]+)[\/]/,     // Matches orders/TEST-ORDER-006/
      ];

      for (const pattern of patterns) {
        const keyMatch = manifestKeyStr.match(pattern);
        if (keyMatch && keyMatch[1]) {
          orderId = keyMatch[1];
          console.log(`✓ Extracted orderId from manifestKey: ${orderId} (pattern matched)`);
          break;
        }
      }

      if (!orderId) {
        console.warn(`⚠️ Could not extract orderId from manifestKey: ${manifestKeyStr.substring(0, 100)}`);
      }
    }
  }

  let webhookUrl = (input.webhookUrl && input.webhookUrl !== null && input.webhookUrl !== '') ? input.webhookUrl : null;
  let dedicationText = (input.dedicationText && input.dedicationText !== null && input.dedicationText !== '') ? input.dedicationText : null;

  // If not found at top level, check body (webhook structure)
  if (!manifestUrl && input.body && input.body !== input) {
    manifestUrl = (input.body.manifestUrl && input.body.manifestUrl !== null && input.body.manifestUrl !== '') ? input.body.manifestUrl : null;
    if (!manifestUrl) {
      manifestUrl = (input.body.originalManifestUrl && input.body.originalManifestUrl !== null && input.body.originalManifestUrl !== '') ? input.body.originalManifestUrl : null;
    }
    if (!orderId) {
      orderId = (input.body.orderId && input.body.orderId !== null && input.body.orderId !== '') ? input.body.orderId : null;
      if (!orderId) {
        orderId = (input.body.amazonOrderId && input.body.amazonOrderId !== null && input.body.amazonOrderId !== '') ? input.body.amazonOrderId : null;
      }
    }
    if (!webhookUrl) {
      webhookUrl = (input.body.webhookUrl && input.body.webhookUrl !== null && input.body.webhookUrl !== '') ? input.body.webhookUrl : null;
    }
    if (!dedicationText) {
      dedicationText = (input.body.dedicationText && input.body.dedicationText !== null && input.body.dedicationText !== '') ? input.body.dedicationText : null;
    }
  }

  // If no manifestUrl but we have orderId, construct it
  // UPDATED: Uses 2B manifest (not 2A) for Workflow 3
  if ((!manifestUrl || manifestUrl === null || manifestUrl === '') && orderId && orderId !== null && orderId !== '') {
    // PRODUCTION URL: https://admin.littleherolabs.com
    // PREVIEW URL: https://387cb69b.little-hero-labs-admin.pages.dev (for testing preview branches)
    const baseUrl = 'https://admin.littleherolabs.com/api/manifests';
    manifestUrl = `${baseUrl}/book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2b-manifest.json`;
    console.log(`✓ Constructed manifestUrl from orderId: ${manifestUrl} (orderId was: ${orderId})`);
  }

  // Final validation - if still no manifestUrl, we have a problem
  if (!manifestUrl || manifestUrl === null || manifestUrl === '') {
    const keys = input ? Object.keys(input).join(', ') : 'no input';
    const manifestUrlValue = input.manifestUrl;
    const orderIdValue = orderId;  // Use the extracted orderId, not input.orderId
    const manifestKeyValue = input.manifestKey || 'not present';
    console.error(`❌ Cannot resolve manifestUrl. manifestUrl=${manifestUrlValue}, orderId=${orderIdValue}, manifestKey=${manifestKeyValue}, Keys: ${keys}`);
    throw new Error(`Cannot resolve manifestUrl. manifestUrl=${manifestUrlValue}, orderId=${orderIdValue}, manifestKey=${manifestKeyValue}, Keys: ${keys}`);
  }

  // CRITICAL: Detect if this is from webhook (first pass) or Wait node (retry loop)
  // On webhook: body.webhookUrl exists, isFirstPass is undefined
  // On Wait node resume: isFirstPass is explicitly false (from Restore JSON After Upload)
  let isFirstPass = input.isFirstPass;
  if (isFirstPass === undefined) {
    // Not set yet - check if this is from webhook (first pass) or Wait node (retry loop)
    // Check for webhookUrl in body (webhook structure) or top-level (already extracted)
    const hasWebhookUrl = !!(webhookUrl || (input.body && input.body !== input && input.body.webhookUrl));
    isFirstPass = hasWebhookUrl ? true : false; // Default to false if we can't determine
  }

  // CRITICAL: Preserve all fields from input, especially isFirstPass, statusUrl, etc.
  // These are essential for routing in the IF node after retry loops
  // Also include manifestKey for downstream nodes
  const manifestKey = `book-mvp-simple-adventure/orders/${orderId}/manifests/2b-manifest.json`;

  return {
    json: {
      ...input,  // Preserve ALL fields from input
      manifestUrl: manifestUrl,
      originalManifestUrl: manifestUrl,
      manifestKey: manifestKey,
      orderId: orderId || input.orderId || input.amazonOrderId || null,
      webhookUrl: webhookUrl || input.webhookUrl || null,
      // Explicitly preserve these critical fields for IF node routing
      isFirstPass: isFirstPass,
      statusUrl: input.statusUrl || input.status_url || null,
      status_url: input.status_url || input.statusUrl || null,
      requestId: input.requestId || input.request_id || null,
      request_id: input.request_id || input.requestId || null,
      poseNumber: input.poseNumber || null,
      characterHash: input.characterHash || null,
      // Include dedicationText from Router payload (explicitly extracted from top-level or body)
      dedicationText: dedicationText || input.dedicationText || null,
      // Include backend URL for downstream proxy URL construction
      backendUrl: 'https://admin.littleherolabs.com'
    }
  };
});

/**
 * Build Assembly Input From Manifest
 * Converts 2B manifest into the payload expected downstream.
 *
 * IMPORTANT:
 * - Prefer bg-removed (nobg) assets when available (bgRemovedKey).
 * - If bg removal did not complete for a pose, fall back to the approved pose PNG (approvedKey)
 *   so W3 does not silently drop characters from pages.
 */
const input = $input.first().json || {};
const manifest = input || {}; // HTTP node passes manifest JSON as item

// Validate manifest schema
if (!manifest.schema || !String(manifest.schema).includes('lhb.run-manifest')) {
  throw new Error(`Invalid or missing manifest schema. Expected 'lhb.run-manifest@v2.x', got: ${manifest.schema || 'undefined'}`);
}

// Try to get preserved context from Extract node (includes dedicationText from Router)
let ctx = {};
try { ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {}; } catch {}

const order = manifest.order || {};
const entries = Array.isArray(manifest.entries) ? manifest.entries : [];

// Accept either amazonOrderId OR orderId
const amazonOrderId = order.amazonOrderId || order.orderId || ctx.orderId || null;
const characterHash = manifest.characterHash || order.characterHash || null;
const backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';

// Extract dedicationText from Router payload (preserved in Extract node)
let dedicationText = ctx.dedicationText ?? null;
if (dedicationText === 'null' || dedicationText === '') dedicationText = null;

if (!amazonOrderId) throw new Error('Manifest missing required order ID (amazonOrderId or orderId)');
if (!characterHash) throw new Error('Manifest missing required characterHash');
if (!Array.isArray(entries) || entries.length === 0) throw new Error('Manifest has no entries (poses)');

// Amazon detection
const isAmazonOrder = !!(
  manifest.marketplace_id === 'ATVPDKIKX0DER' ||
  manifest.marketplaceId === 'ATVPDKIKX0DER' ||
  order.marketplace_id === 'ATVPDKIKX0DER' ||
  order.marketplaceId === 'ATVPDKIKX0DER' ||
  order.amazonOrderId
);
const expectedPageCount = isAmazonOrder ? 17 : 15;

console.log(
  `[W3 Build Assembly] Order Detection: orderId=${amazonOrderId}, ` +
  `isAmazonOrder=${isAmazonOrder}, expectedPageCount=${expectedPageCount}`
);

// Backend proxy URL helper (optionally cache-bust if flipped)
const toProxy = (key, flipped = false, flippedAt = null) => {
  let url = `${backendUrl}/api/assets/${key}`;
  if (flipped && flippedAt) {
    const cacheBuster = new Date(flippedAt).getTime();
    url = `${url}?v=${cacheBuster}`;
  }
  return url;
};

// Build processedImages for ALL poses we can render.
// Prefer bgRemovedKey, but fall back to approvedKey so characters aren't missing.
const missingBgRemovedPoseNumbers = [];

const processedImages = entries
  .filter(e => Number.isFinite(Number(e.poseNumber)) && (e.bgRemovedKey || e.approvedKey))
  .sort((a,b) => Number(a.poseNumber) - Number(b.poseNumber))
  .map(e => {
    const poseNumber = Number(e.poseNumber);
    const key = e.bgRemovedKey || e.approvedKey;

    // Track missing bg removal for story poses (1..12)
    if (poseNumber >= 1 && poseNumber <= 12 && !e.bgRemovedKey) {
      missingBgRemovedPoseNumbers.push(poseNumber);
    }

    const fileName = (String(key).split('/').pop()) || `pose${String(poseNumber).padStart(2,'0')}.png`;
    const flipped = Boolean(e.flipped);
    const flippedAt = e.flippedAt || null;

    return {
      poseNumber,
      fileName,
      r2Path: key,
      publicUrl: toProxy(key, flipped, flippedAt),
      // Distinguish whether this is a real bg-removed image or a fallback
      briaProcessed: Boolean(e.bgRemovedKey),
      briaStatus: e.bgRemovedKey ? 'COMPLETED' : 'NOT_BG_REMOVED',
      processingError: false,
      flipped,
      flippedAt,
      _sourceKey: e.bgRemovedKey ? 'bgRemovedKey' : 'approvedKey'
    };
  });

if (missingBgRemovedPoseNumbers.length) {
  console.warn(
    `[W3 Build Assembly] ⚠️ Missing bgRemovedKey for poses: ${missingBgRemovedPoseNumbers.join(', ')}. ` +
    `Falling back to approvedKey (non-transparent poses).`
  );
}

return [{ json: {
  amazonOrderId,
  characterHash,
  isAmazonOrder,
  expectedPageCount,
  marketplace_id: order.marketplace_id || order.marketplaceId || ctx.marketplace_id || ctx.marketplaceId || null,
  characterSpecs: order.characterSpecs || {},
  bookSpecs: order.bookSpecs || {},
  orderDetails: order.orderDetails || {},
  publicR2Url: order.publicR2Url || null,
  backendUrl,
  processedImages,
  missingBgRemovedPoseNumbers,
  dedicationText
} }];

// Get order ready for book assembly (robust Webhook body handling)

// Webhook puts the real payload under .body; if not present, assume it's already flat
const input = $input.first().json;
const payload = input.body ?? input;

// Pull required fields from either flat or nested orderData
const amazonOrderId = payload.amazonOrderId ?? payload.orderData?.amazonOrderId ?? null;
const characterHash = payload.characterHash ?? payload.orderData?.characterHash ?? null;

// Optional sections
const characterSpecs = payload.characterSpecs ?? payload.orderData?.characterSpecs ?? {};
const bookSpecs      = payload.bookSpecs      ?? payload.orderData?.bookSpecs      ?? {};
const orderDetails   = payload.orderDetails   ?? payload.orderData?.orderDetails   ?? {};
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url    = payload.publicR2Url    ?? null;

// Processed images come in flat (2B sends them at top level)
const processedImages = payload.processedImages ?? [];

// Extract dedicationText from Router payload (passed from Build Assembly Input From Manifest)
// Handle edge case: if value is string null, convert to actual null
let dedicationText = payload.dedicationText ?? null;
if (dedicationText === 'null' || dedicationText === '') {
  dedicationText = null;
}

// Validate
if (!amazonOrderId || !characterHash) {
  throw new Error('Missing required order data: amazonOrderId or characterHash');
}
if (!Array.isArray(processedImages) || processedImages.length === 0) {
  throw new Error('No processed images received from Workflow 2B');
}

// Optional test gating (limit downstream page generations)
// testModePages: explicit numeric value OR default to 2 when testMode === true
const testMode = payload.testMode === true || payload.testMode === 'true';
const testModePages = Number(payload.testModePages ?? (testMode ? 2 : 0)) || 0;

// Amazon vs Standard routing flags (forwarded from manifest/W0 if present)
const isAmazonOrder =
  payload.isAmazonOrder === true ||
  payload.isAmazonOrder === 'true';

// Robust expectedPageCount handling (accept number or numeric string)
let expectedPageCount;
const rawExpected = payload.expectedPageCount ?? null;
const numericExpected = Number(rawExpected);

if (Number.isFinite(numericExpected) && numericExpected > 0) {
  expectedPageCount = Math.floor(numericExpected);
} else {
  expectedPageCount = isAmazonOrder ? 17 : 15;
}

// Normalize/initialize assembly state
const assemblingOrder = {
  status: 'book_assembly_in_progress',
  assemblyStartedAt: new Date().toISOString(),
  pagesGenerated: 0,
  // IMPORTANT: use dynamic expectedPageCount instead of hard-coded 15
  totalPagesRequired: expectedPageCount,
  assemblyProgress: 0,

  amazonOrderId,
  characterHash,
  characterSpecs,
  bookSpecs,
  orderDetails,
  publicR2Url,

  processedImages,

  // Preserve dedicationText from Router payload
  dedicationText,

  // NEW: expose to downstream generators/collectors
  testModePages,

  // Amazon routing flags
  isAmazonOrder,
  expectedPageCount
};

console.log(
  `Starting book assembly for order: ${amazonOrderId} ` +
  `(images: ${processedImages.length}, testModePages=${testModePages}, expectedPageCount=${expectedPageCount}, isAmazonOrder=${isAmazonOrder})`
);

return [{ json: assemblingOrder }];

/**
 * Load story text (v2, 14 pages) + ensure characterImages exists
 * UPDATED: Extract pronouns from manifest and dynamically inject into story
 * FIXED: Last page always uses "They" and hometown default is context-aware
 */
const order = $input.first().json || {};
const childName = order.characterSpecs?.childName;
// Hometown: use provided value, or default to "a cozy town" for first instance
const hometown = order.characterSpecs?.hometown || 'a cozy town';
// For last page, if no hometown provided, use "back to their cozy town"
const hometownReturn = order.characterSpecs?.hometown 
  ? `to ${order.characterSpecs.hometown}` 
  : 'back to their cozy town';
if (!childName) throw new Error('Child name required (characterSpecs.childName)');

const BASE_PREFIX = 'book-mvp-simple-adventure/order-generated-assets/characters';
const publicR2Url = order.publicR2Url || null;

// Character hash (required for canonical pose paths)
const hash = order.characterHash || order.orderData?.characterHash;
if (!hash) throw new Error('Missing characterHash in order payload');

// Resolve backendUrl (for proxy asset URLs)
let backendUrl = order.backendUrl;
if (!backendUrl) {
  try {
    const ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {};
    backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
  } catch {
    backendUrl = 'https://admin.littleherolabs.com';
  }
}

// --- PRONOUNS EXTRACTION & MAPPING ---
const pronounsRaw = order.characterSpecs?.pronouns || '';
const pronounsLower = String(pronounsRaw).toLowerCase().trim();

// Map pronouns to subject/object/possessive forms
function getPronounSet(pronounStr) {
  const p = pronounStr.toLowerCase();

  // She/her
  if (p.includes('she') || p.includes('girl')) {
    return {
      subject: 'she',      // She ran
      object: 'her',       // with her
      possessive: 'her',   // her eyes
      reflexive: 'herself' // she found herself
    };
  }

  // He/him
  if (p.includes('he') || p.includes('boy')) {
    return {
      subject: 'he',       // He ran
      object: 'him',       // with him
      possessive: 'his',   // his eyes
      reflexive: 'himself' // he found himself
    };
  }

  // They/them (default)
  return {
    subject: 'they',      // They ran
    object: 'them',       // with them
    possessive: 'their',  // their eyes
    reflexive: 'themselves' // they found themselves
  };
}

const pronouns = getPronounSet(pronounsLower);

// Capitalize first letter (for sentence starts)
const capitalize = (str) => str.charAt(0).toUpperCase() + str.slice(1);
const SubjectCap = capitalize(pronouns.subject);

// --- Animal name + trailType (prefer assets node outputs) ---
const animalSlug = order.animalImages?.slug || String(order.characterSpecs?.animalGuide || '').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
function displayNameFromSlug(slug) {
  if (slug === 't-rex') return 'T-Rex';
  if (!slug) return 'Tiger';
  return slug.charAt(0).toUpperCase() + slug.slice(1);
}
const animalDisplayName = order.animalImages?.displayName || displayNameFromSlug(animalSlug || 'tiger');

// Map trail type for story copy
let trailType = 'footprints';
if (/(t\\s*-\\s*rex|t\\s*rex|trex|dinosaur)/i.test(animalSlug)) {
  trailType = 'giant footprints';
} else if (/(owl|penguin)/i.test(animalSlug)) {
  trailType = 'feathers';
} else if (/unicorn/i.test(animalSlug)) {
  trailType = 'colorful fur';
} else if (/(lion|tiger|dog|cat)/i.test(animalSlug)) {
  trailType = 'paw prints';
}

// --- Story lines (v2) — UPDATED with dynamic pronouns ---
// FIXED: Last page always uses "They" and context-aware hometown return phrase
const lines = [
  `It was bedtime in ${hometown}. ${childName} closed ${pronouns.possessive} eyes and took a soft breath.<br>"Let's take a dream-walk," a quiet voice whispered.`,
  `Outside, the night sparkled with stars.<br>"Look up," the voice said. "Pause. Breathe. Listen."`,
  `A glowing door opened.<br>"When we listen to our own quiet, new worlds begin to whisper back."`,
  `${childName} floated among the stars.<br>"This is a place your quiet made," the voice whispered.<br>"Whenever the day feels too much, breathe and visit again."`,
  `${childName} noticed a trail of ${trailType} and felt a tiny yes inside.<br>"You can follow me anytime," the voice said. Listening helps you find the way.`,
  `Wind whooshed as ${childName} ran, light and quick.<br>"Listening brings courage," the voice said. "It can feel like joy."`,
  `A wide view appeared.<br>"Sometimes it helps to stop and see how far you've come," the voice said.`,
  `Lunch was waiting."Hungry? Let's eat," the voice said.<br> "Being kind to your body is listening, too."`,
  `"When you look closely, you can find beautiful things," the voice said.<br>${childName} paused and found a shining shell.`,
  `A crystal cave glimmered.<br>"Small steps. Watch where your feet go," the voice said. "Careful can be brave."`,
  `Giant flowers stretched overhead. ${childName} gasped in surprise.<br>"You'll be amazed by what you can grow," the voice said.`,
  `The voice felt very close now, and a trail led deeper between the trees.<br>"To hear me clearly, go quiet inside," it said. "That quiet is your heart."`,
  `${animalDisplayName} stepped from the light, warm and bright.<br>"I've been with you the whole time," said ${animalDisplayName}. "I am your quiet inside voice."`,
  `"Ready to fly home?" asked ${animalDisplayName}. They whooshed through the stars ${hometownReturn}.<br>"Wherever you go—pause, breathe, listen—I'm always with you."`
];

const storyTexts = lines.map((text, i) => ({
  pageNumber: i + 1,
  text,
  characterName: childName,
  hometown,
  animalGuide: animalDisplayName,
  trailType,
  validated: true,
  // ADDED: Include pronoun info for transparency
  pronouns: pronounsRaw,
  pronounsUsed: pronouns
}));

// --- Pose names for alt/fallbacks ---
const poseNames = [
  'walking','walking-looking-higher','looking','floating',
  'walking-looking-down','jogging','looking','sitting-eating',
  'crouching','crawling-moving-happy','surprised-looking-up','surprised'
];

// --- Ensure processedImages exists (fallback synthesize) ---
let processedImages = Array.isArray(order.processedImages) && order.processedImages.length
  ? order.processedImages
  : Array.from({ length: 12 }, (_, i) => {
      const poseNumber = i + 1;
      const padded = String(poseNumber).padStart(2, '0');
      const fileName = `characters_${hash}_pose${padded}_nobg.png`;
      const r2Path = `${BASE_PREFIX}/${hash}/${fileName}`;
      const publicUrl = publicR2Url ? `${publicR2Url}/${r2Path}` : null;
      return {
        poseNumber,
        fileName,
        r2Path,
        publicUrl,
        briaProcessed: true,
        briaStatus: 'COMPLETED',
        processingError: false,
      };
    });

// --- Ensure characterImages from processedImages (idempotent) ---
if (!order.characterImages || !Array.isArray(order.characterImages.poses)) {
  const poses = processedImages
    .filter(pi => Number.isFinite(Number(pi.poseNumber)) && pi.poseNumber >= 1 && pi.poseNumber <= 12)
    .sort((a, b) => Number(a.poseNumber) - Number(b.poseNumber))
    .map(pi => {
      const poseNum = Number(pi.poseNumber);
      const imagePath = pi.publicUrl || (pi.r2Path ? `${backendUrl}/api/assets/${pi.r2Path}` : null);
      return {
        poseNumber: poseNum,
        poseFilename: poseNames[poseNum - 1] || `pose${String(poseNum).padStart(2, '0')}`,
        imagePath,
        pageNumber: poseNum,
        validated: !pi.processingError,
      };
    });

  order.characterImages = {
    base: `${backendUrl}/api/assets/${BASE_PREFIX}/${hash}/base-character.png`,
    poses,
  };
}

// --- Extract dedicationText from order (preserve from Router payload) ---
let dedicationText = order.dedicationText ?? null;
if (dedicationText === 'null' || dedicationText === '') {
  dedicationText = null;
}

// --- Return merged payload ---
return [{
  json: {
    ...order,
    backendUrl,
    publicR2Url,
    storyTexts,
    processedImages,
    trailType,
    animalDisplayName,
    dedicationText: dedicationText,
    // ADDED: Pass through pronouns for debugging/transparency
    pronounsExtracted: pronounsRaw,
    pronounsResolved: pronouns
  }
}];

const order = $input.first().json;
const pagesGenerated = Array.isArray(order.pagePreviewImages) ? order.pagePreviewImages.length : (order.totalPages || 0);

const completed = {
  ...order,
  status: 'book_assembly_previews_ready',
  bookAssemblyCompletedAt: new Date().toISOString(),
  finalBookUrl: undefined,
  totalAssemblyTime: order.assemblyStartedAt ? (new Date() - new Date(order.assemblyStartedAt)) : null,
  averageTimePerPage: order.assemblyStartedAt
    ? Math.round(((new Date() - new Date(order.assemblyStartedAt)) / (order.totalPagesRequired || 15)) / 1000)
    : null,
  pagesGenerated
};

return [{ json: completed }];

const order = $input.first().json;

const logEntry = {
  timestamp: new Date().toISOString(),
  workflow: '3-book-assembly-voice-of-wonder',
  orderId: order.amazonOrderId,
  status: order.status,
  pagesGenerated: order.pagesGenerated,
  totalPagesRequired: order.totalPagesRequired,
  assemblyProgress: order.assemblyProgress,
  finalBookUrl: order.finalBookUrl || 'N/A'
};

console.log('Book Assembly Results:', JSON.stringify(logEntry, null, 2));
return [{ json: logEntry }];

// Idempotency Check - Prevent Duplicate Executions
// Checks if this orderId was recently processed (within last 30 seconds)
// Uses workflow static data to track recent executions

const input = $input.first().json || {};
const orderId = input.orderId || input.amazonOrderId || null;

if (!orderId) {
  // If no orderId, we can't check for duplicates, but we should still proceed
  // (might be a test run or edge case)
  console.warn('⚠️ No orderId found for idempotency check - proceeding anyway');
  return [{ json: input }];
}

const staticData = this.getWorkflowStaticData('global');
const recentExecutions = staticData.recentExecutions || {};
const now = Date.now();
const thirtySecondsAgo = now - 30000;

// Check if this order was recently executed
if (recentExecutions[orderId] && recentExecutions[orderId] > thirtySecondsAgo) {
  const secondsAgo = Math.round((now - recentExecutions[orderId]) / 1000);
  console.log(`⚠️ Duplicate execution detected for orderId: ${orderId} (executed ${secondsAgo}s ago) - skipping`);
  return []; // Empty output stops execution
}

// Record this execution
recentExecutions[orderId] = now;

// Clean up old entries (older than 5 minutes)
const fiveMinutesAgo = now - 300000;
Object.keys(recentExecutions).forEach(key => {
  if (recentExecutions[key] < fiveMinutesAgo) {
    delete recentExecutions[key];
  }
});

staticData.recentExecutions = recentExecutions;

console.log(`✅ Idempotency check passed for orderId: ${orderId}`);

// Pass through original input
return [{ json: input }];

/**
 * Generate Page Preview Images — PARITY (no CSS injected)
 * Emits one item per page for PDFMonkey image template rendering.
 *
 * Output item shape:
 * {
 *   pageHtml, pageImageFilename, pageImageR2Key,
 *   pdfMonkeyImageTemplateId, pdfMonkeyTemplateId,
 *   pageIndex, pageNumber, page_css, useImgBackgrounds
 * }
 */

function get(obj, path, dflt = null) {
  try { return path.split('.').reduce((a, k) => (a && a[k] !== undefined) ? a[k] : undefined, obj) ?? dflt; }
  catch { return dflt; }
}

const input = $input.first()?.json || {};
const order = input || {};
const amazonOrderId = order.amazonOrderId || 'ORDER';

// Carry-through flags for the HTTP body / template payload
const page_css = String(order.page_css || '');
const useImgBackgrounds = Boolean(order.useImgBackgrounds);

// Prefer ids provided by upstream; else fall back to your PNG template id
const PNG_TEMPLATE_ID = order.pdfMonkeyImageTemplateId
  || order.pdfMonkeyTemplateId
  || '23277725-4AB0-446A-98C5-CB99C21822B3';

// backendUrl (not strictly needed here but kept for parity/debug)
const backendUrl =
  order.backendUrl ||
  get($items('Extract Manifest URL (3)', 0, $runIndex), '0.json.backendUrl', 'https://admin.littleherolabs.com');

// --- Collect page fragments ---
// Prefer array from Phase-2; else extract each <div class="book-page" ...>...</div> from pages_html
function extractFragmentsFromPagesHtml(src) {
  const html = String(src || '');
  const re = /<div\s+class=(['"])book-page\1[^>]*>[\s\S]*?<\/div>/gi;
  const out = [];
  let m;
  while ((m = re.exec(html)) !== null) {
    out.push(m[0]);
  }
  // If none matched, fallback to whole string (so we don't silently drop content)
  return out.length ? out : (html.trim() ? [html] : []);
}

// Try to read true pageNumber from id="page-<N>"
function getPageNumberFromFragment(frag, fallback) {
  const m = /id=(['"])page-(\d+)\1/i.exec(String(frag || ''));
  if (m) return Number(m[2]);
  return Number(fallback);
}

let pages = [];
if (Array.isArray(order.interiorPagesHTML) && order.interiorPagesHTML.length) {
  pages = order.interiorPagesHTML.slice();
} else if (typeof order.pages_html === 'string' && order.pages_html.trim()) {
  pages = extractFragmentsFromPagesHtml(order.pages_html);
} else {
  throw new Error('interiorPagesHTML[] or pages_html is required for generating preview images');
}

// If we extracted from a big string, ensure natural order by sorting on pageNumber
if (!Array.isArray(order.interiorPagesHTML) && typeof order.pages_html === 'string') {
  pages = pages
    .map((frag, idx) => ({ frag, n: getPageNumberFromFragment(frag, idx) }))
    .sort((a, b) => a.n - b.n)
    .map(x => x.frag);
}

// --- Build output items (FRAGMENTS ONLY; template provides all CSS) ---
const allItems = [];
for (let i = 0; i < pages.length; i++) {
  const frag = String(pages[i] || '');
  const pageNumber = getPageNumberFromFragment(frag, i); // 0..14
  const stem = 'p' + String(pageNumber).padStart(2, '0'); // keep filenames aligned to pageNumber
  const filename = `${stem}.png`;
  const r2Key = `book-mvp-simple-adventure/orders/${amazonOrderId}/preview-images/${filename}`;

  allItems.push({
    json: {
      amazonOrderId,
      backendUrl,
      pageIndex: i,                // index within this batch
      pageNumber,                  // 0..14 from fragment id when available
      pageHtml: frag,              // FRAGMENT ONLY (no <html>, no <head>, no <style>)
      pageImageFilename: filename,
      pageImageR2Key: r2Key,
      // carry-through for HTTP body payload
      page_css,
      useImgBackgrounds,
      // robust template id
      pdfMonkeyImageTemplateId: PNG_TEMPLATE_ID,
      pdfMonkeyTemplateId: PNG_TEMPLATE_ID
    }
  });
}

// --- Test mode filtering ---
// Accept either:
//  - testModePages: [1,5,12,13]  (array of pageNumbers)
//  - testModePages: 4            (number → keep first N pages by ascending pageNumber)
//  - legacy: from "Get Order Ready for Assembly"
let testMode = get($items('Get Order Ready for Assembly', 0, $runIndex), '0.json.testModePages', null);
if (testMode == null) testMode = order.testModePages ?? null;

let result = allItems;

if (Array.isArray(testMode) && testMode.length) {
  const set = new Set(testMode.map(n => Number(n)));
  result = allItems.filter(it => set.has(Number(it.json.pageNumber)));
} else if (Number.isFinite(Number(testMode)) && Number(testMode) > 0) {
  // Keep first N by ascending pageNumber for determinism
  const sorted = [...allItems].sort((a, b) => Number(a.json.pageNumber) - Number(b.json.pageNumber));
  result = sorted.slice(0, Number(testMode));
}

return result;

// Poll PDFMonkey until image is ready
// When running "Once for Each Item", use $input.item instead of $input.first()
const createResp = $input.item.json;
const doc = createResp.data || createResp.document || createResp;
const docId = doc.id || doc.data?.id;

if (!docId) {
  throw new Error('PDFMonkey create response missing id');
}

const apiBase = 'https://api.pdfmonkey.io/api/v1/documents/';
const http = this.helpers.httpRequest;
const AUTH_HEADER = { Authorization: 'Bearer 2zpxHdmsse2ECXgVVtVR' };

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || null;
let attempts = 0;

async function sleep(ms){ return new Promise(r=>setTimeout(r, ms)); }

while (attempts < 30) {
  if (status === 'success' && downloadUrl) break;
  const resp = await http({ method: 'GET', url: apiBase + docId, json: true, headers: AUTH_HEADER });
  const d = resp.data || resp.document || resp;
  status = d.status;
  downloadUrl = d.download_url || d.file_url || null;
  if (status === 'success' && downloadUrl) break;
  attempts++;
  await sleep(1800 + Math.floor(Math.random()*600));
}

if (status !== 'success' || !downloadUrl) {
  throw new Error(`PDFMonkey image not ready after polling (status=${status})`);
}

// Preserve ALL input context from the current item
const input = $input.item.json;

return {
  json: {
    ...input,
    pdfMonkeyImageDocumentId: docId,
    pageImageDownloadUrl: downloadUrl
  }
};

/**
 * Collect All Page Preview Images (Run once for all items)
 * - Reads original items from "Generate Page Preview Images"
 * - Preserves Cloudflare Images data from input (Store Cloudflare Images ID node output)
 * - Builds progress counters
 */
const SOURCE_NODE = 'Generate Page Preview Images'; // exact node name

const previews = $items(SOURCE_NODE);
if (!previews || previews.length === 0) {
  throw new Error(`No items found from "${SOURCE_NODE}". Ensure that node produced per-page items.`);
}

// Get Cloudflare Images data from current input (Store Cloudflare Images ID node output)
let cloudflareDataMap = new Map();
try {
  const cloudflareItems = $input.all() || [];
  cloudflareItems.forEach(item => {
    const data = item.json || item;
    // Try to get page number from multiple sources
    let pageNum = Number(data.pageNumber);

    // If pageNumber is 0 or invalid, try to extract from filename
    if (!Number.isFinite(pageNum) || pageNum === 0) {
      const filename = data.filename || data.result?.filename || '';
      // Extract page number from filename: p00.png -> 0, p01.png -> 1, etc.
      const match = filename.match(/p(\d+)\.png/i);
      if (match) {
        pageNum = parseInt(match[1], 10);
      }
    }

    if (Number.isFinite(pageNum)) {
      cloudflareDataMap.set(pageNum, {
        cloudflareImageId: data.cloudflareImageId || null,
        cloudflareImageUrl: data.cloudflareImageUrl || null
      });
    }
  });
} catch (e) {
  console.warn(`Could not process Cloudflare Images data from input:`, e.message);
}

const base = previews[0]?.json || {};
const amazonOrderId = base.amazonOrderId || 'ORDER';
const backendUrl = base.backendUrl || 'https://admin.littleherolabs.com';
const publicR2Url = base.publicR2Url || null;

// Helper to form a public URL for an r2Key
function toPublicUrl(r2Key) {
  if (!r2Key) return null;
  if (backendUrl) return `${backendUrl}/api/assets/${r2Key}`;
  if (publicR2Url) return `${publicR2Url.replace(/\/$/, '')}/${r2Key}`;
  return null;
}

// Build page images list from originals, preserving Cloudflare Images data
const pageImages = previews
  .map(it => {
    const j = it.json || {};
    const pageNumber = Number(j.pageNumber);
    const r2Key = j.pageImageR2Key;
    const filename = j.pageImageFilename || (r2Key ? r2Key.split('/').pop() : null);

    if (!Number.isFinite(pageNumber)) return null;

    // Get Cloudflare Images data for this page
    const cfData = cloudflareDataMap.get(pageNumber);

    return {
      pageNumber,
      r2Key,
      filename,
      imageUrl: toPublicUrl(r2Key),
      // Preserve Cloudflare Images data
      cloudflareImageId: cfData?.cloudflareImageId || null,
      cloudflareImageUrl: cfData?.cloudflareImageUrl || null
    };
  })
  .filter(Boolean)
  .sort((a,b) => a.pageNumber - b.pageNumber);

// Progress counters
const pagesGenerated = pageImages.length;

// Derive total pages required from whichever source we have
const totalFromStory = Array.isArray(base.storyTexts) ? base.storyTexts.length : 0;
const totalFromBackgrounds = Array.isArray(base.backgroundImages) ? base.backgroundImages.length : 0;
const totalFromBookSpecs = base.bookSpecs && Number.isFinite(base.bookSpecs.totalPages)
  ? (base.bookSpecs.totalPages - (base.bookSpecs.frontMatterPages || 2))
  : 0;

// Prefer explicit per-story/page assets; fall back to a reasonable number
const totalPagesRequired = Math.max(totalFromStory, totalFromBackgrounds, totalFromBookSpecs, 0) || pageImages.length;
const assemblyProgress = totalPagesRequired > 0
  ? Math.round((pagesGenerated / totalPagesRequired) * 100) / 100
  : 0;

return [{
  json: {
    ...base,
    status: pagesGenerated >= totalPagesRequired ? 'book_assembly_previews_ready' : 'book_assembly_in_progress',
    assemblyStartedAt: base.assemblyStartedAt || new Date().toISOString(),
    pagesGenerated,
    totalPagesRequired,
    assemblyProgress,
    pagePreviewImages: pageImages,
    totalPages: pageImages.length,
    imagesCollectedAt: new Date().toISOString(),
    success: pageImages.length > 0,
  }
}];

/** Build 3A Manifest: interiors + cover + assetsUsed + Cloudflare Images (Phase 4)
 *
 * Supports:
 * - HTML → PNG interiors
 * - HTML → PNG cover spread (flattened)
 * - Cloudflare Images for pages & cover (pageNumber, pageType)
 * - Backwards compatible with legacy coverPdf keys (if present)
 */
const base = $input.first()?.json || {};

// ---------------------------------------------------------------------------
// Phase-1 context (safe reads)
// ---------------------------------------------------------------------------
let inputs = {};
let renderCtx = {};
try {
  const norm = $items('Normalize Inputs (3A Phase 1)1', 0, $runIndex)?.[0]?.json;
  if (norm?.inputs) inputs = norm.inputs;
} catch {}

try {
  const res = $items('Resolve Asset Paths (3A Phase 1)1', 0, $runIndex)?.[0]?.json;
  if (res?.renderContext) renderCtx = res.renderContext;
} catch {}

const amazonOrderId =
  base.amazonOrderId ||
  base.orderId ||
  inputs.orderId ||
  null;

if (!amazonOrderId) {
  throw new Error('amazonOrderId/orderId is required');
}

// ---------------------------------------------------------------------------
// Page preview images
// Expectation: upstream "Collect Page Preview Images" feeds pagePreviewImages
// into this node's input. We do NOT hard-reference that node here.
// ---------------------------------------------------------------------------
const pagePreviewImages = Array.isArray(base.pagePreviewImages)
  ? base.pagePreviewImages
  : [];

console.log('[Build 3A Manifest] pagePreviewImages count:', pagePreviewImages.length);

// ---------------------------------------------------------------------------
// Cloudflare Images map
//   Sources:
//     - Store Cloudflare Images ID1 (pages)
//     - Store Cloudflare Images ID  (cover)
// ---------------------------------------------------------------------------
let cloudflareImagesData = [];

function pushCloudflareFrom(nodeName) {
  try {
    const out = $items(nodeName, 0, $runIndex);
    if (Array.isArray(out)) {
      out.forEach(i => {
        if (i?.json) cloudflareImagesData.push(i.json);
      });
    } else if (out?.json) {
      cloudflareImagesData.push(out.json);
    }
  } catch (e) {
    // Node might not exist or might not run on this path; that's fine.
  }
}

// Interiors path
pushCloudflareFrom('Store Cloudflare Images ID1');
// Cover path
pushCloudflareFrom('Store Cloudflare Images ID');

const cloudflareMap = new Map();
let coverCloudflareImageId = null;
let coverCloudflareImageUrl = null;

cloudflareImagesData.forEach(cf => {
  if (!cf) return;
  const pageType = cf.pageType || cf.type || null;
  const pageNumRaw =
    cf.pageNumber !== undefined ? cf.pageNumber : cf.pageNum;
  const cfId  = cf.cloudflareImageId || null;
  const cfUrl = cf.cloudflareImageUrl || null;

  // COVER-SPREAD: pageType:'cover-spread' OR pageNumber:-1
  if (pageType === 'cover-spread' || Number(pageNumRaw) === -1) {
    if (cfId || cfUrl) {
      coverCloudflareImageId  = cfId  || coverCloudflareImageId;
      coverCloudflareImageUrl = cfUrl || coverCloudflareImageUrl;
      cloudflareMap.set(-1, {
        cloudflareImageId: cfId,
        cloudflareImageUrl: cfUrl,
      });
    }
    return;
  }

  // Interior pages (0..N)
  const pageNum = Number(pageNumRaw);
  if (!Number.isFinite(pageNum)) return;

  const existing = cloudflareMap.get(pageNum) || {};
  cloudflareMap.set(pageNum, {
    cloudflareImageId: cfId || existing.cloudflareImageId || null,
    cloudflareImageUrl: cfUrl || existing.cloudflareImageUrl || null,
  });
});

// Merge any CF info already attached on pagePreviewImages
pagePreviewImages.forEach(p => {
  const pageNum = Number(p.pageNumber);
  if (!Number.isFinite(pageNum)) return;

  const cfId  = p.cloudflareImageId;
  const cfUrl = p.cloudflareImageUrl;
  if (!cfId && !cfUrl) return;

  const existing = cloudflareMap.get(pageNum) || {};
  cloudflareMap.set(pageNum, {
    cloudflareImageId: cfId || existing.cloudflareImageId || null,
    cloudflareImageUrl: cfUrl || existing.cloudflareImageUrl || null,
  });
});

// ---------------------------------------------------------------------------
// pageImageUrls for W4 (Cloudflare preferred → R2 → direct URL)
//   Interiors only; cover handled separately.
// ---------------------------------------------------------------------------
const backendBase = base.backendUrl || 'https://admin.littleherolabs.com';

const pageImageUrls = pagePreviewImages
  .map(p => {
    const pageNum = Number(p.pageNumber ?? p.pageIndex ?? 0);
    const cfData = cloudflareMap.get(pageNum);
    if (cfData?.cloudflareImageUrl) return cfData.cloudflareImageUrl;
    if (p.r2Key) return `${backendBase}/api/assets/${p.r2Key}`;
    return p.imageUrl || null;
  })
  .filter(Boolean);

// ---------------------------------------------------------------------------
// COVER (PNG) KEYS — flattened cover spread
// ---------------------------------------------------------------------------
let coverImageKey = null;
try {
  const fromSet =
    $items('Set Cover PNG Filenames/Keys', 0, $runIndex)?.[0]?.json || {};
  if (fromSet.coverPngR2Key) coverImageKey = fromSet.coverPngR2Key;
} catch {}

try {
  const fromUpload =
    $items('Upload Cover Preview Image to R2 (3A1)', 0, $runIndex)?.[0]?.json || {};
  if (!coverImageKey && fromUpload.coverPngR2Key) {
    coverImageKey = fromUpload.coverPngR2Key;
  }
} catch {}

// Also accept if already on input
if (!coverImageKey && base.coverPngR2Key) {
  coverImageKey = base.coverPngR2Key;
}

// If no explicit CF cover yet, try from map(-1)
if (!coverCloudflareImageId && !coverCloudflareImageUrl) {
  const coverCfData = cloudflareMap.get(-1) || null;
  if (coverCfData) {
    coverCloudflareImageId  = coverCfData.cloudflareImageId || null;
    coverCloudflareImageUrl = coverCfData.cloudflareImageUrl || null;
  }
}

// No active cover PDF nodes yet — keep backward compat only if present on input
const coverPdfKey = base.coverPdfR2Key || null;

// ---------------------------------------------------------------------------
// Pages map (R2 keys) + pagesWithCloudflare
// ---------------------------------------------------------------------------
const pages = {};
const pagesWithCloudflare = {};

// Page 0 (dedication) - REMOVED: Only use p00_dedication, not p00
// This eliminates redundancy and makes the manifest cleaner
let page0Processed = false;
for (const p of pagePreviewImages) {
  const pageNum = Number(p.pageNumber);
  if (pageNum === 0) {
    const key =
      p.r2Key ||
      p.pageImageR2Key ||
      p.imageR2Key ||
      p.key ||
      p.path ||
      null;

    if (key) {
      // REMOVED: pages.p00 = key; (redundant with p00_dedication)
      pages.p00_dedication = key;  // Keep only the semantic key
      page0Processed = true;

      const cfData =
        cloudflareMap.get(0) || {
          cloudflareImageId: p.cloudflareImageId || null,
          cloudflareImageUrl: p.cloudflareImageUrl || null,
        };

      if (cfData.cloudflareImageId || cfData.cloudflareImageUrl) {
        const entry = {
          cloudflareImageId: cfData.cloudflareImageId || null,
          cloudflareImageUrl: cfData.cloudflareImageUrl || null,
        };

        // REMOVED: pagesWithCloudflare.p00 = entry; (redundant with p00_dedication)
        pagesWithCloudflare.p00_dedication = entry;  // Keep only the semantic key
      }
    }
    break;
  }
}

if (!page0Processed) {
  console.warn(
    '[Build 3A Manifest] PAGE 0 not found. pageNumbers:',
    pagePreviewImages.map(p => p.pageNumber),
  );
}

// Pages 1..N (dynamic)
// Previously limited to 1..14; now accepts any positive pageNumber.
pagePreviewImages.forEach(p => {
  const n = Number(p.pageNumber);
  if (!Number.isFinite(n) || n < 1) return;

  const key =
    p.r2Key ||
    p.pageImageR2Key ||
    p.imageR2Key ||
    p.key ||
    p.path ||
    null;

  if (!key) return;

  const id = n < 10 ? `p0${n}` : `p${n}`;
  pages[id] = key;

  const cfData =
    cloudflareMap.get(n) || {
      cloudflareImageId: p.cloudflareImageId || null,
      cloudflareImageUrl: p.cloudflareImageUrl || null,
    };

  if (cfData.cloudflareImageId || cfData.cloudflareImageUrl) {
    pagesWithCloudflare[id] = {
      cloudflareImageId: cfData.cloudflareImageId || null,
      cloudflareImageUrl: cfData.cloudflareImageUrl || null,
    };
  }
});

// ---------------------------------------------------------------------------
// Assets used
// ---------------------------------------------------------------------------
const overlaysUsed = [];
try {
  const assetsSrc = $items('Load Canonical Assets', 0, $runIndex)?.[0]?.json || {};
  const ov = assetsSrc.overlayImages;
  if (Array.isArray(ov)) {
    ov.forEach(o => { if (o?.r2Key) overlaysUsed.push(o.r2Key); });
  } else if (ov && typeof ov === 'object') {
    Object.values(ov).forEach(o => { if (o?.r2Key) overlaysUsed.push(o.r2Key); });
  }
} catch {}

const assetsUsed = {
  font:             renderCtx?.font || 'book-mvp-simple-adventure/fonts/custom-font.ttf',
  coversBg:         renderCtx?.coversBg || 'book-mvp-simple-adventure/backgrounds/page00-covers.png',
  coversBgAmazon:   renderCtx?.coversBgAmazon || null,
  dedicationBg:     renderCtx?.dedicationBg || 'book-mvp-simple-adventure/backgrounds/page00-dedication.png',
  pose00:           renderCtx?.pose00 || null,
  overlays:         overlaysUsed,
};

// ---------------------------------------------------------------------------
// Manifest assembly
// ---------------------------------------------------------------------------
const nowIso = new Date().toISOString();

const manifest = {
  schema: 'lhb.run-manifest@v2.0',
  runStamp: nowIso,
  // Get characterHash from multiple sources (preserve from 2B manifest)
  characterHash: (() => {
    // Priority: 1) base input, 2) Load Story & Character Poses, 3) Get Order Ready for Assembly, 4) Build Assembly Input From Manifest
    if (base.characterHash) return base.characterHash;
    try {
      const storyNode = $items('Load Story & Character Poses (3A)', 0, $runIndex)?.[0]?.json;
      if (storyNode?.characterHash) return storyNode.characterHash;
    } catch {}
    try {
      const readyNode = $items('Get Order Ready for Assembly', 0, $runIndex)?.[0]?.json;
      if (readyNode?.characterHash) return readyNode.characterHash;
    } catch {}
    try {
      const buildNode = $items('Build Assembly Input From Manifest', 0, $runIndex)?.[0]?.json;
      if (buildNode?.characterHash) return buildNode.characterHash;
    } catch {}
    return null;
  })(),
  amazonOrderId,

  pngGeneration: {
    sizeInterior: { w: 2625, h: 2625 },
    sizeCover:    { w: 5203, h: 2625 },
    pages,
    pagesWithCloudflare,
    coverSpreadImage: coverImageKey || null,
    coverCloudflareImageId: coverCloudflareImageId || null,
    coverCloudflareImageUrl: coverCloudflareImageUrl || null,
  },

  pdfGeneration: {
    coverPdf: coverPdfKey || null,
  },

  assetsUsed,
  pages,

  summary: {
    percentComplete: 100,
    readyForBook: true,
    needsHumanReview: true,
  },

  generatedAt: nowIso,
};

console.log(
  '[Build 3A Manifest] FINAL pages:',
  Object.keys(manifest.pngGeneration.pages),
);

// ---------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------
return [
  {
    json: {
      manifest,
      orderId: amazonOrderId,
      characterHash: manifest.characterHash,
      pagePreviewImages,
      pageImageUrls,
      coverImage: manifest.pngGeneration.coverSpreadImage,
      coverPngR2Key: coverImageKey || null,
      coverPdfR2Key: coverPdfKey || null,
      coverCloudflareImageId: coverCloudflareImageId || null,
      coverCloudflareImageUrl: coverCloudflareImageUrl || null,
      cloudflareImagesSummary: {
        totalItems: cloudflareImagesData.length,
        pagesWithCloudflare: Object.keys(pagesWithCloudflare).length,
        coverHasCloudflare: !!coverCloudflareImageId,
      },
    },
  },
];

/**
 * Prep Manifest Upload (3) - Convert manifest to binary format for R2 upload
 */
const data = $input.first().json;
const manifest = data.manifest;
const orderId = data.orderId;

if (!manifest || !manifest.schema) {
  throw new Error('Manifest is missing or invalid in Prep Manifest Upload (3)');
}

if (!orderId) {
  throw new Error('orderId is required for Prep Manifest Upload (3)');
}

// Construct R2 key for 3-manifest
const manifestKey = `book-mvp-simple-adventure/orders/${orderId}/manifests/3-manifest.json`;

console.log(`Preparing to upload 3-manifest to: ${manifestKey}`);

// Convert manifest to buffer for upload
const manifestJSON = JSON.stringify(manifest, null, 2);
const buffer = Buffer.from(manifestJSON, 'utf-8');

return [{
  json: {
    ...data,
    manifestKey: manifestKey,
    manifestBucket: 'little-hero-orders'
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/json',
      fileName: '3-manifest.json',
      fileExtension: 'json'
    }
  }
}];

/**
 * Load Background Images (pages 1..N) + ensure overlays & animal 'appears'/'flying'
 * Backgrounds live at: book-mvp-simple-adventure/backgrounds/pageXX-<slug>.png
 * Page 5 trail overlays: book-mvp-simple-adventure/overlays/animal-tracks/page05-meadow-<variant>.png
 *   Variants: clawprints | footprints | fur | owl-feathers | penguin-feathers
 * Animal sprites (pages 13–14):
 *   book-mvp-simple-adventure/characters/animals/<slug>-appears.png
 *   book-mvp-simple-adventure/characters/animals/<slug>-flying.png
 *
 * NOTE: This node is the single source of truth for:
 *   - backgroundImages
 *   - overlayImages (including Page 5 trail variant selection)
 *   - animalImages { slug, displayName, appears, flying }
 * It intentionally does NOT create storyTexts.
 */
const order = $input.first().json || {};

// ---- Context / backend URL ----
let backendUrl = order.backendUrl;
if (!backendUrl) {
  try {
    const ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {};
    backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
  } catch {
    backendUrl = 'https://admin.littleherolabs.com';
  }
}

// Keep this requirement if you want to enforce real orders; remove if you need previews without an order id.
if (!order.amazonOrderId) {
  throw new Error('Amazon Order ID is required for loading background images');
}

// ---- Backgrounds (core scene definitions) ----
const sceneSlugs = [
  'twilight-walk','night-forest','magic-doorway','courage-leap','morning-meadow',
  'tall-forest','mountain-vista','picnic-surprise','beach-discovery','crystal-cave',
  'giant-flowers','almost-there','animal-reveal','flying-home'
];
const sceneNames = [
  'twilight_walk','night_forest','magic_doorway','courage_leap','morning_meadow',
  'tall_forest','mountain_vista','picnic_surprise','beach_discovery','crystal_cave',
  'giant_flowers','enchanted_grove','animal_reveal','flying_home'
];

// Determine how many interior pages should get backgrounds.
// expectedPageCount includes dedication; interior pages = expectedPageCount - 1.
// Defaults preserve legacy behavior (14 interior pages → 15 total incl. p00).
const rawExpected = order.expectedPageCount ?? null;
const numericExpected = Number(rawExpected);
let interiorPageCount;

if (Number.isFinite(numericExpected) && numericExpected > 1) {
  // total pages includes p00 dedication; interior = total - 1
  interiorPageCount = Math.floor(numericExpected) - 1;
} else {
  // Legacy default: 15 total (p00 + p01..p14)
  interiorPageCount = 14;
}

// Dedication background (page 0)
const dedication = {
  pageNumber: 0,
  imagePath: `${backendUrl}/api/assets/book-mvp-simple-adventure/backgrounds/page00-dedication.png`,
  sceneName: 'dedication',
  validated: false,
};

// Build backgrounds for pages 1..interiorPageCount
// For pages beyond the 14 defined scenes, reuse the last scene (flying_home)
// so we don't introduce new, non-existent assets.
const backgroundImages = [
  dedication,
  ...Array.from({ length: interiorPageCount }, (_, i) => {
    const pageNumber = i + 1;
    const idx = Math.min(i, sceneSlugs.length - 1); // clamp to last known scene
    const slug = sceneSlugs[idx];
    const sceneName = sceneNames[idx];

    const r2Key = `book-mvp-simple-adventure/backgrounds/page${String(pageNumber).padStart(2,'0')}-${slug}.png`;
    const imagePath = `${backendUrl}/api/assets/${r2Key}`;
    return { pageNumber, imagePath, sceneName, validated: false };
  })
];

// ---- Helpers: normalize, title, animal slug, overlay variant ----
const animalGuideRaw = order.characterSpecs?.animalGuide || order.animalGuide || '';
const aKey = String(animalGuideRaw).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

function animalSlugFromKey(k) {
  if (/^(t\s*rex|t\s*-\s*rex|trex|dinosaur)$/.test(k)) return 't-rex';
  if (/^owl$/.test(k)) return 'owl';
  if (/^penguin$/.test(k)) return 'penguin';
  if (/^unicorn$/.test(k)) return 'unicorn';
  if (/^lion$/.test(k)) return 'lion';
  if (/^tiger$/.test(k)) return 'tiger';
  if (/^dog$/.test(k)) return 'dog';
  if (/^cat$/.test(k)) return 'cat';
  // fallback to cat to guarantee an asset exists
  return 'cat';
}

function displayNameFromSlug(slug) {
  if (slug === 't-rex') return 'T-Rex';
  return slug.charAt(0).toUpperCase() + slug.slice(1);
}

function overlayVariantForSlug(slug) {
  // T-Rex uses clawprints
  if (slug === 't-rex') return 'clawprints';
  // Owl and penguin use feathers
  if (slug === 'owl') return 'owl-feathers';
  if (slug === 'penguin') return 'penguin-feathers';
  // Unicorn uses fur
  if (slug === 'unicorn') return 'fur';
  // Cats, dogs, lions, tigers use footprints
  if (['cat', 'dog', 'lion', 'tiger'].includes(slug)) return 'footprints';
  // Fallback to footprints
  return 'footprints';
}

const animalSlug = animalSlugFromKey(aKey);
const animalDisplay = displayNameFromSlug(animalSlug);

// ---- Page 5 overlay selection by animal → variant ----
const p5Variant = overlayVariantForSlug(animalSlug);
const p5OverlayKey = `book-mvp-simple-adventure/overlays/animal-tracks/page05-meadow-${p5Variant}.png`;
const p5OverlayUrl = `${backendUrl}/api/assets/${p5OverlayKey}`;
const p5OverlayEntry = {
  pageNumber: 5,
  imagePath: p5OverlayUrl,
  kind: 'trail',
  variant: p5Variant,
  r2Key: p5OverlayKey,
  validated: true,
};

// Merge into overlayImages (supports array or object), replacing any old Page 5 entry
let overlayImages = order.overlayImages ?? order.overlays ?? null;

function isP5(o) {
  const pn = Number(o?.pageNumber);
  return pn === 5 || /(^|[^0-9])05([^0-9]|$)/.test(String(o?.r2Key || o?.imagePath || ''));
}

if (Array.isArray(overlayImages)) {
  overlayImages = overlayImages.filter(o => !isP5(o));
  overlayImages.push(p5OverlayEntry);
} else if (overlayImages && typeof overlayImages === 'object') {
  overlayImages.page05 = p5OverlayEntry;
  overlayImages.p05 = p5OverlayEntry;
  overlayImages.trail = p5OverlayEntry;
} else {
  overlayImages = [p5OverlayEntry];
}

// ---- Dynamic Animal images for Pages 13 & 14 (no hardcoding) ----
const animalsBase = `book-mvp-simple-adventure/characters/animals`;
const appearsKey = `${animalsBase}/${animalSlug}-appears.png`;
const flyingKey  = `${animalsBase}/${animalSlug}-flying.png`;
const appearsUrl = `${backendUrl}/api/assets/${appearsKey}`;
const flyingUrl  = `${backendUrl}/api/assets/${flyingKey}`;

let animalImages = order.animalImages || {};
animalImages = {
  ...animalImages,
  slug: animalSlug,
  displayName: animalImages.displayName || (order.animalDisplayName || animalDisplay),
  // Appear (Page 13)
  appearsR2Key: appearsKey,
  appears: appearsUrl,
  appearsImagePath: appearsUrl,
  imageAppears: appearsUrl,
  // Flying (Page 14)
  flyingR2Key: flyingKey,
  flying: flyingUrl,
  flyingImagePath: flyingUrl,
  imageFlying: flyingUrl,
};

const coverSpreadImagePath = `${backendUrl}/api/assets/book-mvp-simple-adventure/covers/cover-spread.png`;

// ---- Extract dedicationText from order (preserve from Router payload) ----
// CRITICAL: Check multiple sources to ensure we don't lose dedicationText
// Priority: 1) current order, 2) Get Order Ready for Assembly, 3) Build Assembly Input From Manifest, 4) Extract Manifest URL
let dedicationText = order.dedicationText ?? null;

// Fallback: Check upstream nodes if not found in current order
if (!dedicationText || dedicationText === 'null' || dedicationText === '') {
  try {
    const readyNode = $items('Get Order Ready for Assembly', 0, $runIndex)?.[0]?.json;
    if (readyNode?.dedicationText && readyNode.dedicationText !== 'null' && readyNode.dedicationText !== '') {
      dedicationText = readyNode.dedicationText;
    }
  } catch {}
}

if (!dedicationText || dedicationText === 'null' || dedicationText === '') {
  try {
    const buildNode = $items('Build Assembly Input From Manifest', 0, $runIndex)?.[0]?.json;
    if (buildNode?.dedicationText && buildNode.dedicationText !== 'null' && buildNode.dedicationText !== '') {
      dedicationText = buildNode.dedicationText;
    }
  } catch {}
}

if (!dedicationText || dedicationText === 'null' || dedicationText === '') {
  try {
    const extractNode = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json;
    if (extractNode?.dedicationText && extractNode.dedicationText !== 'null' && extractNode.dedicationText !== '') {
      dedicationText = extractNode.dedicationText;
    }
  } catch {}
}

// Final normalization: convert string 'null' or empty string to actual null
if (dedicationText === 'null' || dedicationText === '') {
  dedicationText = null;
}

// ---- Merge and return ----
return [{
  json: {
    ...order,
    backendUrl,
    backgroundImages,
    overlayImages,     // includes correct Page 5 trail overlay
    animalImages,      // dynamic appears + flying tied to animal
    coverSpreadImagePath,
    // CRITICAL: Explicitly preserve dedicationText from Router payload (must be in output)
    dedicationText: dedicationText,
  }
}];

/**
 * QA Gate (3A Phase 4) — tolerant for Cover PDF or PNG; p00 optional.
 * Inputs: expects Build 3A Manifest upstream
 * Checks:
 *  - schema
 *  - interior size (2625×2625)
 *  - optional cover PNG size (5203×2625) if present
 *  - pages present (p01..pNN; NN = highest page in manifest.pages)
 *  - p00_dedication optional (warn only)
 *  - at least one of: cover PNG key OR cover PDF key
 */
const j = $json || {};
const manifest = j.manifest || j;

const out = {
  pass: true,
  reasons: [],
  checks: []
};

function add(label, pass, extra = {}) {
  out.checks.push({ label, pass, ...extra });
  if (!pass) out.pass = false;
}

// 1) Schema
const schemaOk = manifest.schema === 'lhb.run-manifest@v2.0';
add('schema present & correct', schemaOk, { schema: manifest.schema });

// 2) Interior size
const sizeInterior = manifest.pngGeneration?.sizeInterior || { w: 2625, h: 2625 };
add(
  'interior PNG size is 2625×2625',
  sizeInterior.w === 2625 && sizeInterior.h === 2625,
  { sizeInterior }
);

// 3) Cover PNG size (if present)
const sizeCover = manifest.pngGeneration?.sizeCover || { w: 5203, h: 2625 };
const hasCoverPng = !!manifest.pngGeneration?.coverSpreadImage;
add(
  'cover PNG size is 5203×2625',
  hasCoverPng ? (sizeCover.w === 5203 && sizeCover.h === 2625) : true,
  { sizeCover, skipped: !hasCoverPng }
);

// 4) Pages present: require p01..pNN (dedication p00_dedication optional)
const pages = manifest.pages || {};

// Determine highest page present from keys like p01, p02, ..., p16
const pageKeys = Object.keys(pages).filter(k => /^p\d{2}$/.test(k));
let maxPageNum = 0;
for (const key of pageKeys) {
  const n = parseInt(key.slice(1), 10);
  if (Number.isFinite(n) && n > maxPageNum) {
    maxPageNum = n;
  }
}

// If there are no interior pages at all, that's a hard fail
let missing = [];
if (maxPageNum > 0) {
  const required = Array.from({ length: maxPageNum }, (_, i) => {
    const n = i + 1;
    return n < 10 ? `p0${n}` : `p${n}`;
  });
  missing = required.filter(k => !pages[k]);
  add(
    'all pages present (p01..pNN)',
    missing.length === 0,
    { missing, expectedCount: maxPageNum }
  );
} else {
  add('all pages present (p01..pNN)', false, {
    missingReason: 'no interior page keys (p01..pNN) found in manifest.pages',
    expectedCount: 0
  });
}

if (pages.p00_dedication == null) {
  // Not failing if dedication is absent; warn only
  out.reasons.push('p00_dedication missing (warning only)');
}

// 5) Page keys non-null
const nullish = Object.entries(pages)
  .filter(([k, v]) => v == null || (typeof v === 'object' && v.key == null))
  .map(([k]) => k);
add('page keys are non-null', nullish.length === 0, { nullish });

// 6) Cover present: either a PNG key OR a Cover PDF key
const coverKeyPng = manifest.pngGeneration?.coverSpreadImage || null;
const coverKeyPdf = manifest.pdfGeneration?.coverPdf || j.coverPdfR2Key || null;
const hasCover = !!(coverKeyPng || coverKeyPdf);
add('cover present (PNG or PDF)', hasCover, { coverPngKey: coverKeyPng, coverPdfKey: coverKeyPdf });

// 7) Assets present
add('font asset present', !!manifest.assetsUsed?.font, { font: manifest.assetsUsed?.font });
add('coversBg asset present', !!manifest.assetsUsed?.coversBg, { coversBg: manifest.assetsUsed?.coversBg });
add('dedicationBg asset present', !!manifest.assetsUsed?.dedicationBg, { dedicationBg: manifest.assetsUsed?.dedicationBg });

// 8) Overlays optional
add('p05 overlay declared', true, { overlays: manifest.assetsUsed?.overlays || [] });

// Summary
if (!out.pass) {
  const reasons = out.checks.filter(c => !c.pass).map(c => c.label);
  out.reasons = [...out.reasons, ...reasons];
  throw new Error('QA Gate failed: ' + JSON.stringify(out));
}

return [{ json: { ...j, qa: out } }];

/**
 * Acceptance Tests (3A Phase 5)
 * - Compiles a Markdown report and a machine-readable verdict
 * - Reads manifest from "Build 3A Manifest" and page images from "Collect Page Preview Images"
 */
// Gather upstream artifacts
let manifest = null;
let collector = null;
let qa = null;
try { manifest  = $items('Build 3A Manifest', 0, $runIndex)?.[0]?.json?.manifest || null; } catch {}
try { collector = $items('Collect Page Preview Images', 0, $runIndex)?.[0]?.json || null; } catch {}
try { qa = $items('QA Gate (3A Phase 4)', 0, $runIndex)?.[0]?.json?.qa || null; } catch {}

if (!manifest) throw new Error('Acceptance: manifest not found');

const pages = (manifest.pngGeneration && manifest.pngGeneration.pages) || manifest.pages || {};
const pageKeys = Object.keys(pages || {});

// Derive interior pages p01..pNN dynamically from manifest.pages
const interiorKeys = pageKeys.filter(k => /^p\d{2}$/.test(k));
let maxPageNum = 0;
for (const key of interiorKeys) {
  const n = parseInt(key.slice(1), 10);
  if (Number.isFinite(n) && n > maxPageNum) {
    maxPageNum = n;
  }
}

const expectedInteriorKeys = maxPageNum > 0
  ? Array.from({ length: maxPageNum }, (_, i) => {
      const n = i + 1;
      return n < 10 ? `p0${n}` : `p${n}`;
    })
  : [];

// p00_dedication is required for acceptance (unlike QA, which only warns)
const expectedKeys = ['p00_dedication', ...expectedInteriorKeys];
const missing = expectedKeys.filter(k => !(k in pages));
const coverKey = manifest.pngGeneration?.coverSpreadImage || null;

// Verdict booleans
const sizesOk = manifest.pngGeneration?.sizeInterior?.w === 2625
             && manifest.pngGeneration?.sizeInterior?.h === 2625
             && manifest.pngGeneration?.sizeCover?.w === 5203
             && manifest.pngGeneration?.sizeCover?.h === 2625;

const hasAllPages = missing.length === 0
  && expectedKeys.every(k => {
    const v = pages[k];
    return typeof v === 'string'
      ? !!v
      : !!(v && (v.key || v.path || v.r2Key));
  });

const coverOk = !!coverKey;
const qaPass = !!(qa && qa.pass === true);

const collectedCount = Number(collector?.pagePreviewImages?.length || 0);
let testModePagesFromReady = 0;
try {
  testModePagesFromReady =
    Number($items('Get Order Ready for Assembly', 0, $runIndex)?.[0]?.json?.testModePages || 0) || 0;
} catch {}

// Total expected preview images (dedication + interior pages)
// Standard: 1 + 14 = 15; Amazon: 1 + 16 = 17; etc.
const totalExpectedPages = 1 + expectedInteriorKeys.length;
const expectedCollectorCount =
  testModePagesFromReady > 0 ? testModePagesFromReady : totalExpectedPages;

const matchesCollector =
  hasAllPages && (collectedCount >= expectedCollectorCount);

const verdict = {
  sizesOk,
  hasAllPages,
  coverOk,
  qaPass,
  matchesCollector,
  readyToUploadManifest: sizesOk && hasAllPages && coverOk && qaPass
};

// Markdown report
function badge(ok){ return ok ? '✅' : '❌'; }
const lines = [];
lines.push(`# Workflow 3A — Acceptance Report`);
lines.push(`Generated: ${new Date().toISOString()}`);
lines.push('');
lines.push(`**Order:** ${manifest.amazonOrderId || 'UNKNOWN'}  `);
lines.push(`**Character Hash:** ${manifest.characterHash || 'UNKNOWN'}  `);
lines.push('');
lines.push(`## Summary`);
lines.push(`- Sizes: ${badge(verdict.sizesOk)} interior 2625×2625; cover 5203×2625`);
lines.push(`- Pages present: ${badge(verdict.hasAllPages)} (expected ${totalExpectedPages} incl. dedication)`);
lines.push(`- Cover image present: ${badge(verdict.coverOk)}`);
lines.push(`- QA Gate: ${badge(verdict.qaPass)}`);
lines.push(`- Collector consistency: ${badge(verdict.matchesCollector)} (pages=${collectedCount}, expected>=${expectedCollectorCount})`);
lines.push('');
if (missing.length) {
  lines.push(`**Missing pages:** ${missing.join(', ')}`);
  lines.push('');
}
lines.push('## Assets Used');
const au = manifest.assetsUsed || {};
lines.push(`- Font: \`${au.font || 'n/a'}\``);
lines.push(`- Covers BG: \`${au.coversBg || 'n/a'}\``);
lines.push(`- Dedication BG: \`${au.dedicationBg || 'n/a'}\``);
lines.push(`- Overlays: ${Array.isArray(au.overlays) ? au.overlays.map(k => `\`${k}\``).join(', ') : 'n/a'}`);
lines.push('');
lines.push('## Page Keys');
expectedKeys.forEach(k => {
  const v = pages[k];
  let val = (typeof v === 'string')
    ? v
    : (v && (v.key || v.path || v.r2Key) || 'null');
  lines.push(`- ${k}: ${val ? '`' + val + '`' : '`null`'}`);
});

const reportMd = lines.join('\n');

return [{
  json: {
    reportMd,
    verdict,
    manifestSummary: {
      orderId: manifest.amazonOrderId || null,
      characterHash: manifest.characterHash || null,
      coverKey
    }
  }
}];

/**
 * Build Exact Parity Page (Decoupled width/height/position/padding)
 * - Single HTML for ONE page, pixel-accurate.
 * - Width & Height independent; AR used only if height=auto.
 * - Center-anchored positioning; 4-side text insets; <br> → newline.
 */

const input = $input.first()?.json || {};
const order = input || {};
const RUN_BUST = encodeURIComponent(order.runStamp || order.runId || Date.now());

// ---- config: choose which page to preview (0..14). Default 5. ----
const TARGET_PAGE = Number(order.tunerPage ?? 5);

// ---- backend base ----
let backendUrl = order.backendUrl;
if (!backendUrl) {
  try {
    const ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {};
    backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
  } catch {
    backendUrl = 'https://admin.littleherolabs.com';
  }
}

// ---- helpers ----
function toAbsoluteAsset(u){
  const s = String(u || '').trim();
  if (!s) return '';
  if (/^https?:\/\//i.test(s)) return s;
  return `${backendUrl}/api/assets/${s.replace(/^\/+/, '')}`;
}
function withBust(u){
  if (!u) return '';
  const sep = u.includes('?') ? '&' : '?';
  return `${u}${sep}v=${RUN_BUST}`;
}
function norm(u){ return withBust(toAbsoluteAsset(u)); }
const firstStr = (...vals) => vals.find(v => typeof v === 'string' && v.trim().length) || '';
function deepFindUrl(obj, keyRegex) {
  try {
    const seen = new Set(); const stack = [obj];
    while (stack.length) {
      const cur = stack.pop();
      if (!cur || typeof cur !== 'object' || seen.has(cur)) continue;
      seen.add(cur);
      for (const [k, v] of Object.entries(cur)) {
        if (keyRegex.test(String(k))) {
          if (typeof v === 'string' && v) return v;
          if (v && typeof v === 'object') {
            const hit = firstStr(v.imagePath, v.url, v.publicUrl, v.href);
            if (hit) return hit;
          }
        }
        if (v && typeof v === 'object') stack.push(v);
      }
    }
  } catch {}
  return '';
}

// ---- assets/text from order ----
const getTextBoxOverlayUrl = () =>
  `${backendUrl}/api/assets/book-mvp-simple-adventure/overlays/text-boxes/standard-box.png`;

const bgRaw  = (i) => order.backgroundImages?.find(b => Number(b.pageNumber) === Number(i))?.imagePath || '';
const bgUrl  = norm(bgRaw(TARGET_PAGE));

const overlayUrl = (() => {
  const overlays = order.overlayImages || order.overlays || {};
  if (Array.isArray(overlays)) {
    const hit = overlays.find(o => Number(o.pageNumber) === Number(TARGET_PAGE) && (o.imagePath || o.url || o.publicUrl || o.r2Key));
    if (hit) return withBust(toAbsoluteAsset(firstStr(hit.imagePath, hit.url, hit.publicUrl, hit.r2Key)));
  } else if (overlays && typeof overlays === 'object') {
    const re = TARGET_PAGE === 5 ? /animal|trail|footprint|p05|page.?5/i
            : TARGET_PAGE === 12 ? /sparkle|glow|p12|page.?12/i
            : null;
    if (re) {
      const cand = deepFindUrl(overlays, re);
      if (cand) return withBust(toAbsoluteAsset(cand));
    }
  }
  if (TARGET_PAGE === 5) {
    return withBust(`${backendUrl}/api/assets/book-mvp-simple-adventure/overlays/footprints/footprints.png`);
  }
  return null;
})();

// text helpers: normalize <br> to newline, widont, escape
function normalizeBreaks(s){
  return String(s || '').replace(/\s*<br\s*\/?>\s*/gi, '\n');
}
function widont(seg){ return String(seg).replace(/\s+([^\s]{1,12})$/u, '\u00A0$1'); }
function formatText(raw){
  const t = normalizeBreaks(raw);
  return t.split(/\r?\n/).map(v=>widont(v.trim())).join('\n');
}
function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, (m) => (
    {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[m]
  ));
}
const rawText = order.storyTexts?.find(s => Number(s.pageNumber) === Number(TARGET_PAGE))?.text || '';
const text    = escapeHtml(formatText(rawText));

// ---- HTML/CSS: parity canvas with decoupled controls ----
const TEMPLATE_CSS = `
