/* Text inside the overlay with PER-SIDE insets */
.text-content{
  position:absolute;
  top:    var(--tb-inset-top,    var(--text-inset-top));
  right:  var(--tb-inset-right,  var(--text-inset-right));
  bottom: var(--tb-inset-bottom, var(--text-inset-bottom));
  left:   var(--tb-inset-left,   var(--text-inset-left));
  z-index:1;

  display:flex;
  align-items: var(--tb-text-valign, var(--text-vertical-align)); /* vertical centering by default */
  justify-content: center; /* center block horizontally in the padded area */
  text-align:center;

