}

// ---- polling loop ----
for (let attempt = 0; attempt < maxAttempts; attempt++) {
  if (status === 'success' && downloadUrl) break;

  const resp = await http({
    method: 'GET',
    url: `${apiBase}${docId}`,
    json: true,
    headers: AUTH_HEADER,
  });

  const d = resp.data || resp.document || resp;

  status = d.status;
  downloadUrl = d.download_url || d.file_url || downloadUrl;

  if (status === 'error' || status === 'failure') {
    throw new Error(`PDFMonkey reported error status for cover PNG: ${status}`);
  }

  if (status === 'success' && downloadUrl) break;

  await sleep(1800 + Math.floor(Math.random() * 600));
}

if (status !== 'success' || !downloadUrl) {
  throw new Error(`PDFMonkey cover PNG not ready after polling (status=${status})`);
}

// ---- derive correct orderId ----
const orderId =
  orderCtx.orderId ||
  orderCtx.amazonOrderId ||
  orderCtx.AmazonOrderId;

if (!orderId) {
  throw new Error('Missing orderId/amazonOrderId when building coverPngR2Key');
}

// ---- choose filename for R2 ----
// We standardize to cover-spread.png in preview-images.
let filename = 'cover-spread.png';

try {
  const rawMeta = createDoc.meta;
  if (rawMeta) {
    const meta = typeof rawMeta === 'string' ? JSON.parse(rawMeta) : rawMeta;
    if (meta._filename) {
      // Strip any placeholder like "_ORDER" but DO NOT derive orderId from it.
      filename = String(meta._filename).replace('_ORDER', '') || filename;
    }
  }
} catch (e) {
  // non-fatal; keep default filename
}

// Final R2 key for the cover PNG
const coverPngR2Key = `book-mvp-simple-adventure/orders/${orderId}/preview-images/${filename}`;

// ---- return merged context ----
return {
  json: {
    ...input,
    orderId, // ensure the real orderId is carried forward
    pdfMonkeyCoverDocumentId: docId,
    coverPngDownloadUrl: downloadUrl,
    coverPngR2Key,
  },
};

/**
 * Normalize Inputs (3A Phase 1)
 * - Trims/clamps human text inputs.
 * - Produces a compact `inputs` object for downstream HTML builders.
 * Output: { inputs }
 */
const order = $input.first().json || {};

function s(v){ return (v == null) ? '' : String(v); }
function trim(v){ return s(v).replace(/\s+/g,' ').trim(); }
function clamp(str, max){ const t = s(str); return t.length > max ? t.slice(0, max) : t; }
function safeMultiline(str, max){ 
  let out = s(str).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  if (out.length > max) out = out.slice(0, max);
  return out;
}

// Source fields
const cs  = order.characterSpecs || {};
const bs  = order.bookSpecs || {};
const od  = order.orderDetails || {};

// Dedication can come from multiple places (prefer Router payload, then orderDetails)
// Router passes dedicationText at top level, 2B manifest may have it in orderDetails/bookSpecs
// CRITICAL: Check upstream nodes if order.dedicationText is missing
let dedicationRaw = order.dedicationText ?? null;

// Fallback: Check upstream nodes if not found in current order
if (!dedicationRaw || dedicationRaw === 'null' || dedicationRaw === '') {
  try {
    const loadStory = $items('Load Story & Character Poses (3A)', 0, $runIndex)?.[0]?.json;
    if (loadStory?.dedicationText && loadStory.dedicationText !== 'null' && loadStory.dedicationText !== '') {
      dedicationRaw = loadStory.dedicationText;
    }
  } catch {}
}

if (!dedicationRaw || dedicationRaw === 'null' || dedicationRaw === '') {
  try {
    const loadAssets = $items('Load Canonical Assets', 0, $runIndex)?.[0]?.json;
    if (loadAssets?.dedicationText && loadAssets.dedicationText !== 'null' && loadAssets.dedicationText !== '') {
      dedicationRaw = loadAssets.dedicationText;
    }
  } catch {}
}

// Final fallbacks: orderDetails and bookSpecs
if (!dedicationRaw || dedicationRaw === 'null' || dedicationRaw === '') {
  dedicationRaw = od.dedicationMessage ?? bs.dedicationMessage ?? '';
}
const hometownRaw   = cs.hometown ?? od.shippingAddress?.city ?? '';

// Title/subtitle
let title    = trim(bs.title || '');
let subtitle = trim(bs.subtitle || '');

// Defaults
if (!title) title = "Alex and the Adventure Compass";

// Core inputs
const inputs = {
  title: clamp(title, 90),
  subtitle: clamp(subtitle, 120),
  dedicationMessage: safeMultiline(dedicationRaw, 400),
  hometown: clamp(hometownRaw, 60),
  childName: clamp(cs.childName || '', 40),
};

return [{ json: { inputs } }];

/**
 * Resolve Asset Paths (3A Phase 1) — HOTFIX
 * Robustly derives orderId/characterHash from multiple upstream nodes,
 * then emits deterministic R2 keys for cover & page assets.
 * Output: { renderContext, isAmazonOrder, expectedPageCount }
 */
function pick(...vals){ for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; } return null; }
function tryItems(name){
  try { return $items(name, 0, $runIndex)?.[0]?.json || null; } catch { return null; }
}

const in0 = $input.first()?.json || null;
const fromBuild   = tryItems('Build Assembly Input From Manifest');
const fromReady   = tryItems('Get Order Ready for Assembly');
const fromManHTTP = (()=>{
  const m = tryItems('Download 2B Manifest') || {};
  const o = m.order || {};
  return {
    amazonOrderId: o.amazonOrderId,
    characterHash: m.characterHash || o.characterHash,
    characterSpecs: o.characterSpecs,
    bookSpecs: o.bookSpecs,
    orderDetails: o.orderDetails
  };
})();

// Assemble unified context
const ctx = {
  backendUrl: pick(in0?.backendUrl, tryItems('Extract Manifest URL (3)')?.backendUrl, 'https://admin.littleherolabs.com'),
  amazonOrderId: pick(in0?.amazonOrderId, fromBuild?.amazonOrderId, fromReady?.amazonOrderId, fromManHTTP?.amazonOrderId),
  characterHash: pick(in0?.characterHash, fromBuild?.characterHash, fromReady?.characterHash, fromManHTTP?.characterHash),
  // CRITICAL: Preserve Amazon routing fields
  isAmazonOrder: pick(in0?.isAmazonOrder, fromBuild?.isAmazonOrder, fromReady?.isAmazonOrder) || false,
  expectedPageCount: pick(in0?.expectedPageCount, fromBuild?.expectedPageCount, fromReady?.expectedPageCount) || 15,
};

if (!ctx.amazonOrderId || !ctx.characterHash) {
  const dbg = { have: { in0: !!in0, fromBuild: !!fromBuild, fromReady: !!fromReady, fromManHTTP: !!fromManHTTP },
                fields: { amazonOrderId: ctx.amazonOrderId, characterHash: ctx.characterHash } };
  throw new Error('Resolve Asset Paths: unable to derive orderId/characterHash → ' + JSON.stringify(dbg));
}

// Deterministic R2 keys
const fontKey         = 'book-mvp-simple-adventure/fonts/CustomBook.ttf';
const coversBgKey     = 'book-mvp-simple-adventure/backgrounds/page00-covers.png';
const dedicationBgKey = 'book-mvp-simple-adventure/backgrounds/page00-dedication.png';
const p05OverlayKey   = 'book-mvp-simple-adventure/overlays/pages/page05-overlay.png';
const p12OverlayKey   = 'book-mvp-simple-adventure/overlays/pages/page12-overlay.png';
const pose00Key       = `book-mvp-simple-adventure/order-generated-assets/characters/${ctx.characterHash}/base-character.png`;
const blankBgKey      = 'book-mvp-simple-adventure/backgrounds/page00-blank.png';
const titlePageBgKey  = 'book-mvp-simple-adventure/backgrounds/page00-title-page.png';
const coversBgStandardKey = coversBgKey;
const coversBgAmazonKey   = 'book-mvp-simple-adventure/backgrounds/page00-covers-barcode.png';

const renderContext = {
  font: fontKey,
  // cover backgrounds
  coversBg: coversBgKey,            // legacy default
  coversBgStandard: coversBgStandardKey,
  coversBgAmazon: coversBgAmazonKey,
  // special pages
  dedicationBg: dedicationBgKey,
  blankBg: blankBgKey,
  titlePageBg: titlePageBgKey,
  // overlays & character
  p05Overlay: p05OverlayKey,
  p12Overlay: p12OverlayKey,
  pose00: pose00Key,
  // misc context
  backendUrl: ctx.backendUrl,
  orderId: ctx.amazonOrderId,
  characterHash: ctx.characterHash
};

return [{ 
  json: { 
    renderContext,
    // CRITICAL: Pass through Amazon routing fields for IF node
    isAmazonOrder: ctx.isAmazonOrder,
    expectedPageCount: ctx.expectedPageCount
  } 
}];

// Keep the binary AND reattach keys needed later
const base = $items('Set Cover PNG Filenames/Keys')?.[0]?.json || {};
return [{
  json: {
    ...$json,
    orderId: base.orderId,
    coverPdfR2Key: base.coverPdfR2Key,
    coverPdfFilename: base.coverPdfFilename,
  },
  // <-- THIS preserves the downloaded file
  binary: $binary
}];

// Store Cloudflare Images ID
// Combines page data from R2 upload with Cloudflare Images response
// Outputs: pageNumber, pageType, r2Key, cloudflareImageId, cloudflareImageUrl, orderId, imageUrl, ...

const cloudflareResponse = $input.all();

// Get the original page data from upstream nodes
// Prefer the node that carried R2 keys, then fall back gracefully.
let pageData = [];
try {
  pageData = $items('Carry Page Keys Forward1').all();
} catch (e) {
  try {
    pageData = $items('Upload Cover Preview Image to R2 (3A)1').all();
  } catch (e2) {
    console.warn('[Store CF] Could not find upstream nodes, using input data');
    const allItems = $input.all();
    pageData = allItems.map(item => item.json || item);
  }
}

const results = [];
const accountHash = 'JE-pa9WKaCMtKxy6dQQG7A';

for (let i = 0; i < pageData.length; i++) {
  const page = pageData[i] || {};
  const cloudflare = cloudflareResponse[i];

  let cloudflareImageId = null;
  let cloudflareImageUrl = null;

  // Meta from Cloudflare (most reliable)
  let meta = {};
  if (cloudflare && cloudflare.json && cloudflare.json.result && cloudflare.json.result.meta) {
    meta = cloudflare.json.result.meta || {};
  }

  let pageNumberFromMetadata =
    meta.pageNumber !== undefined ? meta.pageNumber :
    meta.pageNum !== undefined ? meta.pageNum :
    null;

  let pageTypeFromMetadata =
    meta.pageType || meta.type || null;

  let orderIdFromMetadata =
    meta.orderId || meta.amazonOrderId || null;

  if (cloudflare && cloudflare.json) {
    console.log(
      `[Cloudflare Images] Item ${i + 1} response:`,
      JSON.stringify(cloudflare.json, null, 2)
    );

    const res = cloudflare.json.result;

    if (res) {
      // Single image
      if (res.id) {
        cloudflareImageId = res.id;
      }
      // Batch-style: result.images[0]
      else if (Array.isArray(res.images) && res.images[0] && res.images[0].id) {
        cloudflareImageId = res.images[0].id;
      }
    }

    if (cloudflareImageId && accountHash) {
      cloudflareImageUrl = `https://imagedelivery.net/${accountHash}/${cloudflareImageId}/public`;
    }

    if (cloudflare.json.errors && cloudflare.json.errors.length > 0) {
      console.error(`[Cloudflare Images] Item ${i + 1} errors:`, cloudflare.json.errors);
    }

    if (cloudflare.json.success === false) {
      console.warn(`[Cloudflare Images] Item ${i + 1} upload failed:`, cloudflare.json);
    }
  } else if (cloudflare && cloudflare.error) {
    console.error(
      `[Cloudflare Images] Item ${i + 1} HTTP error:`,
      cloudflare.error.message || cloudflare.error
    );
  } else {
    console.warn(`[Cloudflare Images] Item ${i + 1} has no response data`);
  }

  // Strip reserved keys like "error"
  const { error, ...pageDataWithoutError } = page;

  // --- Resolve pageNumber (covers + interiors) ---

  let finalPageNumber;

  if (pageNumberFromMetadata !== null && pageNumberFromMetadata !== undefined) {
    // Allow numeric pageNumber, including -1 for cover
    const n = Number(pageNumberFromMetadata);
    finalPageNumber = Number.isNaN(n) ? pageNumberFromMetadata : n;
  } else if (page.pageNumber !== undefined || page.pageNum !== undefined) {
    const n = Number(page.pageNumber ?? page.pageNum);
    finalPageNumber = Number.isNaN(n) ? 0 : n;
  } else if (pageTypeFromMetadata === 'cover-spread' || page.isCover) {
    // Explicit cover fallback
    finalPageNumber = -1;
  } else {
    // Last resort: index
    finalPageNumber = i;
  }

  // --- Resolve orderId ---
  const finalOrderId =
    orderIdFromMetadata ||
    page.orderId ||
    page.amazonOrderId ||
    null;

  // --- Resolve pageType (for clarity) ---
  const finalPageType =
    pageTypeFromMetadata ||
    page.pageType ||
    (finalPageNumber === -1 ? 'cover-spread' : 'interior');

  // --- Resolve r2Key ---
  const r2Key =
    page.pageImageR2Key ||
    page.r2Key ||
    page.coverImageR2Key || // cover spread key support
    page.key ||
    page.fileName ||
    null;

  results.push({
    pageNumber: finalPageNumber,
    pageType: finalPageType,
    r2Key,
    cloudflareImageId,
    cloudflareImageUrl,
    orderId: finalOrderId,
    imageUrl: page.imageUrl || null,
    ...pageDataWithoutError
  });
}

console.log(
  `[Cloudflare Images] Processed ${results.length} items, ${
    results.filter(r => r.cloudflareImageId).length
  } with Cloudflare IDs`
);

return results;

