      // Required: amazon_order_id (for upsert matching)
      amazon_order_id: amazonOrderId,

      // 3 manifest URL
      manifest_3_url: manifestUrl,

      // Overall status for post-Pdf stage (matches OrderStatus enum)
      // Review is ALWAYS needed after W3, so always set to pending_assembly_review
      status: 'pending_assembly_review',

      // Review stages with merged data (preserves preBria and postBria)
      review_stages: reviewStages,

      // Always set next_workflow to '4' after W3 completes
      // Review happens in UI, then approval triggers workflow 4 (not via router)
      next_workflow: '4',

      // Set execution_status - review is ALWAYS needed, so always 'processing'
      // Stays in processing until approval, then approval button sets ready_for_processing
      execution_status: 'processing',

      // Don't clear processing state - approval button handles transition
      // Keep started_at and current_workflow until approval

      workflow_step: 'book_assembly_completed',
      updated_at: new Date().toISOString(),
    };
  })()
}}

