/**
 * Generate Cover HTML (3A) — ALTERNATIVE IMG TAG VERSION
 * Use this if background-image doesn't work in PDF Monkey
 */

let inputs = {};
let renderCtx = {};
try {
  inputs    = $items('Normalize Inputs (3A Phase 1)1', 0, $runIndex)?.[0]?.json?.inputs || {};
  renderCtx = $items('Resolve Asset Paths (3A Phase 1)1', 0, $runIndex)?.[0]?.json?.renderContext || {};
} catch {}

const orderCtx = $input.first().json || {};

// ---- backend base ----
let backendUrl = renderCtx.backendUrl || orderCtx.backendUrl;
if (!backendUrl) {
  try {
    const ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {};
    backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
  } catch {
    backendUrl = 'https://admin.littleherolabs.com';
  }
}

// ---- Reliability toggle: CSS backgrounds vs real <img> layers ----
// DEFAULT: true (more deterministic in PDFMonkey); allow explicit false
const useImgBackgrounds =
  orderCtx.useImgBackgrounds === false
    ? false
    : Boolean(orderCtx.useImgBackgrounds ?? renderCtx.useImgBackgrounds ?? true);

// ---- URL helpers: normalize -> absolute + cache-bust ----
const RUN_BUST = encodeURIComponent(orderCtx.runStamp || orderCtx.runId || Date.now());
function toAbsoluteAsset(u) {
  const s = String(u || '').trim();
  if (!s) return '';
  if (/^https?:\/\//i.test(s)) return s;
  return `${backendUrl}/api/assets/${s.replace(/^\/+/, '')}`;
}
function withBust(u) {
  if (!u) return '';
  const sep = u.includes('?') ? '&' : '?';
  return `${u}${sep}v=${RUN_BUST}`;
}
function norm(u) {
  return withBust(toAbsoluteAsset(u));
}


// ---- helpers ----
const esc = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

// ---- minimal preload helper (only when using <img> layers) ----
function preloadHTML(urls) {
  const uniq = Array.from(new Set((urls || []).filter(u => typeof u === 'string' && u)));
  if (!uniq.length) return '';
  const imgs = uniq
    .map(u => `<img src="${esc(u)}" width="1" height="1" alt="" loading="eager" decoding="sync" fetchpriority="high">`)
    .join('');
  return `<div class="__preloads" style="position:absolute;left:-9999px;top:-9999px;width:1px;height:1px;overflow:hidden;opacity:0;visibility:hidden;">${imgs}</div>`;
}

// ---- cover layer emitters (CSS bg vs <img> toggle) ----
// Cover uses composite: pose (top) + background (bottom)
function coverBgLayerHTML(bgUrl) {
