const order = $input.first().json || {};

// ---- order type & page count ----
// Standard orders: 15 pages total (0..14) → page 0 = dedication, pages 1-14 = story
// Amazon orders: 17 pages total (0..16) → page 0 = title, page 1 = blank, page 2 = dedication, pages 3-16 = story
const isAmazonOrder =
