  9:{left:1352,top:2066,w:1100}, 10:{left:1275,top:2295,w:1300},
  11:{left:1964,top:2117,w:500}, 12:{left:893, top:2066,w:920},
  14:{left:1225,top:2040,w:1500}
};
const OV3   = { left:1020, top:2090, w:1100, rotate:0 };
const OV4   = { left:1530, top:1734, w:1100, rotate:-20 };
const OV14C = { left:1225, top:2040, w:1500, rotate:0 };

function charStyle(n){
  // Images are pre-oriented from R2 - no flipping needed

  if (n === 3) {
    return [
      `left:${toPx(OV3.left)}`,
      `top:${toPx(OV3.top)}`,
      `transform:translate(-50%,-100%)`,
      `width:${toPx(OV3.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }

  if (n === 4) {
    return [
      `left:${toPx(OV4.left)}`,
      `top:${toPx(OV4.top)}`,
      `transform:translate(-50%,-100%) rotate(-20deg)`,
      `width:${toPx(OV4.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }

  if (n === 14) {
    return [
      `left:${toPx(OV14C.left)}`,
      `top:${toPx(OV14C.top)}`,
      `transform:translate(-50%,-100%)`,
      `width:${toPx(OV14C.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }

  const c = CHAR[n];
  if (!c) return '';

  return [
    `left:${toPx(c.left)}`,
    `top:${toPx(c.top)}`,
    `transform:translate(-50%,-100%)`,
    `width:${toPx(c.w)}`,
    `z-index:11`
  ].join('; ') + ';';
}

// ---- text helpers ----
function normalizeBreaks(s){
  return String(s || '')
    .replace(/(?:<\s*br\s*\/?\s*>|&lt;\s*br\s*\/?\s*&gt;)/gi, '\n')
    .replace(/\r\n/g, '\n');
}
function widont(seg) {
  return String(seg).replace(/\s+([^\s]{1,12})$/u, '\u00A0$1');
}
function formatText(raw){
  const s = normalizeBreaks(raw);
  return s.split(/\n/).map(v => widont(v.trim())).join('\n');
}
function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, (m) => (
    {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[m]
  ));
}

// ---- minimal preload helper ----
function preloadHTML(urls){
  const uniq = Array.from(new Set((urls || []).filter(u => typeof u === 'string' && u)));
  if (!uniq.length) return '';
  const imgs = uniq
    .map(u => `<img src="${u}" width="1" height="1" alt="" loading="eager" decoding="sync" fetchpriority="high">`)
    .join('');
  return `<div class="__preloads" style="position:absolute;left:-9999px;top:-9999px;width:1px;height:1px;overflow:hidden;opacity:0;visibility:hidden;">${imgs}</div>`;
}

// ---- background/overlay layer emitters ----
function bgLayerHTML(url){
  if (!url) return '';
  if (!useImgBackgrounds) {
    return `<div class="page-bg" style="background-image:url('${url}');"></div>`;
  }
  return `<div class="page-bg"><img src="${url}" alt="" loading="eager" decoding="sync" fetchpriority="high" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;"></div>`;
}
function overlayLayerHTML(url){
  if (!url) return '';
  if (!useImgBackgrounds) {
    return `<div class="page-overlay" style="background-image:url('${url}');"></div>`;
  }
  return `<div class="page-overlay"><img src="${url}" alt="" loading="eager" decoding="sync" fetchpriority="high" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;"></div>`;
}

// ---- animal sprites ----
function getAnimalSrc(kind){
  const a = order.animalImages || order.animal || {};
  const direct = kind === 'appears'
    ? firstStr(a.appears, a.appear, a.page13, a.p13, a.animalAppears, a.appearsImagePath, a.appearsUrl, a.imageAppears)
    : firstStr(a.flying, a.fly, a.page14, a.p14, a.animalFlying, a.flyingImagePath, a.flyingUrl, a.imageFlying);
  if (direct) return norm(direct);
  const regex = kind === 'appears' ? /appear|p13|page.?13/i : /flying|fly|p14|page.?14/i;
  const deep  = deepFindUrl(a, regex);
  if (deep) return norm(deep);
  const deepOrder = deepFindUrl(order, regex);
  return deepOrder ? norm(deepOrder) : '';
}

function animalHTML(storyPageNum){
  const name = order.animalDisplayName || 'Animal';
  if (storyPageNum === 13) {
    const src = getAnimalSrc('appears');
    if (!src) return `<div class="animal missing" data-missing="page13-appears"></div>`;
