.page-bg, .page-overlay {
  position: absolute;
  inset: 0;
  background-repeat: no-repeat;
  background-position: center center;
  background-size: cover;
}
.dedication-wrap {
  position: absolute;
  left: ${int(0.15 * PX)}px;
  right: ${int(0.15 * PX)}px;
  top: ${int(0.20 * PX)}px;
  bottom: ${int(0.20 * PX)}px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
}
.dedication-text {
  width: 100%;
  text-align: center;
  font-size: ${(26/72) * PX_PER_IN}px;
  line-height: 1.4;
  letter-spacing: 1px;
  color: #312116;
  font-family: 'CustomBook', Arial, sans-serif;
}
.character, .animal { position: absolute; }
.character img, .animal img { width:100%; height:auto; display:block; }
`;

